41	export class LeaseTakenError extends Error {
42	  constructor(resource, holder, requested = undefined, available = undefined) {
43	    super(`lease for resource ${String(resource)} is already held`);
44	    this.name = 'LeaseTakenError';
45	    this.code = LeaseTakenError.code;
46	    this.resource = resource;
47	    this.holder = holder ?? null;
48	    this.requested = requested;
49	    this.available = available;
50	  }
51	}
52	LeaseTakenError.code = 'LEASE_TAKEN';
