87	// Binary min-heap ordered by (expiresAt, insertion order). Expiry heaps are
88	// used three ways: one global heap drives reclamation, each resource gets one
89	// for lazy capacity accounting, and each quota node gets one for lazy quota
90	// accounting. Renewals push fresh nodes and retire the old ones, so reclaiming
91	// expired leases only walks entries that are actually due instead of scanning
92	// the whole table.
93	class ExpiryQueue {
94	  constructor() {
95	    this.nodes = [];
96	  }
97	
98	  get size() {
99	    return this.nodes.length;
100	  }
101	
102	  push(node) {
103	    const nodes = this.nodes;
104	    nodes.push(node);
105	    let i = nodes.length - 1;
106	    while (i > 0) {
107	      const parent = (i - 1) >> 1;
108	      if (expiresBefore(nodes[i], nodes[parent])) {
109	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
110	        i = parent;
111	      } else {
112	        break;
113	      }
114	    }
115	  }
116	
117	  peek() {
118	    return this.nodes[0];
119	  }
120	
121	  pop() {
122	    const nodes = this.nodes;
123	    const top = nodes[0];
124	    const last = nodes.pop();
125	    if (nodes.length > 0) {
126	      nodes[0] = last;
127	      let i = 0;
128	      for (;;) {
129	        const left = i * 2 + 1;
130	        const right = left + 1;
131	        let next = i;
132	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
133	          next = left;
134	        }
135	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
136	          next = right;
137	        }
138	        if (next === i) {
139	          break;
140	        }
141	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
142	        i = next;
143	      }
144	    }
145	    return top;
146	  }
147	}
148	
149	function expiresBefore(a, b) {
150	  if (a.expiresAt !== b.expiresAt) {
151	    return a.expiresAt < b.expiresAt;
152	  }
153	  return a.order < b.order;
154	}
