156	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
157	// requests in deadline order instead of scanning every pending request, so
158	// a large waiting population costs O(expired * log n), never O(n) per call.
159	class DeadlineQueue {
160	  constructor() {
161	    this.nodes = [];
162	  }
163	
164	  get size() {
165	    return this.nodes.length;
166	  }
167	
168	  push(node) {
169	    const nodes = this.nodes;
170	    nodes.push(node);
171	    let i = nodes.length - 1;
172	    while (i > 0) {
173	      const parent = (i - 1) >> 1;
174	      if (deadlineBefore(nodes[i], nodes[parent])) {
175	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
176	        i = parent;
177	      } else {
178	        break;
179	      }
180	    }
181	  }
182	
183	  peek() {
184	    return this.nodes[0];
185	  }
186	
187	  pop() {
188	    const nodes = this.nodes;
189	    const top = nodes[0];
190	    const last = nodes.pop();
191	    if (nodes.length > 0) {
192	      nodes[0] = last;
193	      let i = 0;
194	      for (;;) {
195	        const left = i * 2 + 1;
196	        const right = left + 1;
197	        let next = i;
198	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
199	          next = left;
200	        }
201	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
202	          next = right;
203	        }
204	        if (next === i) {
205	          break;
206	        }
207	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
208	        i = next;
209	      }
210	    }
211	    return top;
212	  }
213	}
214	
215	function deadlineBefore(a, b) {
216	  if (a.deadline !== b.deadline) {
217	    return a.deadline < b.deadline;
218	  }
219	  return a.tie < b.tie;
220	}
221	
222	let registrySequence = 0;
223	let atomicFileSequence = 0;
224	
225	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
226	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
227	    throw new TypeError('ttlMs must be a positive finite number');
228	  }
229	  if (typeof clock !== 'function') {
230	    throw new TypeError('clock must be a function');
231	  }
232	
233	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
234	  const defaultTtlMs = ttlMs;
235	  // resource -> FIFO array of queue positions. A group request listing the
236	  // same resource in several rows occupies one position per row.
237	  const waitQueues = new Map();
238	  // requestId -> group, while the request is still queued.
239	  const pendingGroups = new Map();
240	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq, chain,
241	  // epoch, counted }
242	  const leases = new Map();
243	  // Every token this instance knows about, including replayed credentials
244	  // that were already released or reclaimed, so a freshly minted token can
245	  // never reuse a dead credential's string.
246	  const knownTokens = new Set();
247	  // resource -> Set of tokens currently attached to it. A share resource
248	  // usually carries several live credentials; the set makes release and
249	  // reclaim O(1) regardless of how many shares coexist.
250	  const slots = new Map();
251	  // resource -> last committed credential epoch. The first grant of a
252	  // resource opens it at 1 and every later committed credential advances it
253	  // by exactly one, including retakes by the same holder and credentials
254	  // handed to woken requests. A release, reclaim, expiry or restart never
255	  // moves it backwards, so a resource with no live lease still reports the
256	  // epoch its last credential carried.
257	  const epochs = new Map();
258	  // resource -> runtime bookkeeping. Created lazily; an undeclared resource
259	  // is a capacity-1 resource with no quota chain.
260	  const resourceStates = new Map();
261	  // quota id -> { id, parentId, limit, live, heap, resources }. `live` is the
262	  // current share occupation counted against the limit, maintained per share
263	  // grant and released lazily by the quota's own expiry heap.
264	  const quotas = new Map();
265	  // The global expiry heap drives sweep(); resource and quota heaps drive
266	  // lazy, sub-linear availability checks.
267	  const expiryQueue = new ExpiryQueue();
268	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
269	  // their request only until the next lazy pop, flagged `dead`.
270	  const deadlineQueue = new DeadlineQueue();
271	
272	  const counters = {
273	    granted: 0,
274	    renewed: 0,
275	    released: 0,
276	    reclaimed: 0,
277	  };
278	
279	  // Per-instance identity makes tokens unique across registries living in the
280	  // same process; one instance can never present a token another owns.
281	  registrySequence += 1;
282	  const registryId = registrySequence;
283	  let tokenSequence = 0;
284	  let queueOrder = 0;
285	  let deadlineTie = 0;
286	  let requestSequence = 0;
287	  let batchSequence = 0;
288	  // Monotonic id stamped on every persisted event; a snapshot records the
289	  // last id it folded in, so a log still containing the folded prefix (the
290	  // log swap failed) replays those events as no-ops instead of twice.
291	  let eventSeq = 0;
292	
293	  function mintToken(now, seq = tokenSequence) {
294	    // Pure candidate: nothing is committed until the event is on disk, so a
295	    // failed append rolls all the way back. Pids and instance ids can coincide
296	    // after a restart, so skip any sequence that collides with a credential
297	    // reconstructed from the log. The caller threads the sequence through when
298	    // it mints several tokens for one atomic write.
299	    let token;
300	    do {
301	      seq += 1;
302	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
303	    } while (knownTokens.has(token));
304	    return { token, seq };
305	  }
306	
307	  function newExpiryNode(token, expiresAt, heapSeq) {
308	    return { token, expiresAt, heapSeq, order: queueOrder++ };
309	  }
310	
311	  // One node in every heap a lease occupies. The nodes are independent: each
312	  // heap retires its own stale entries lazily. Every push also bumps the
313	  // owner's heap version, so a reconcile at an unchanged reading still
314	  // re-judges after a grant or renewal changed the heap contents.
315	  // Push one lease node to the global expiry heap and to every owner
316	  // whose heap drives lazy observation. A share already recorded as
317	  // retired at an owner (a replay structurally superseding an unswept
318	  // lease) only needs its global node - it must be reclaimable - and is
319	  // skipped on that owner's heap, since its occupation was never
320	  // reconstructed there. Every other push bumps the owner's heap
321	  // version, so a reconcile at an unchanged reading still re-judges
322	  // after a grant or renewal changed the heap contents.
323	  function pushLeaseHeaps(token, lease) {
324	    const node = newExpiryNode(token, lease.expiresAt, lease.heapSeq);
325	    expiryQueue.push(node);
326	    const rs = resourceStates.get(lease.resource);
327	    rs.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
328	    rs.version += 1;
329	    for (const quota of lease.chain) {
330	      quota.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
331	      quota.version += 1;
332	    }
333	  }
334	
335	  // Peek an owner heap for a lease that is live at `now` without
336	  // mutating anything: stale nodes are inspected but left in place for a
337	  // later reconcile to retire or for a dropStaleSlots displacement.
338	  function hasLiveHeapNode(owner, now) {
339	    for (const node of owner.heap.nodes) {
340	      const lease = leases.get(node.token);
341	      if (lease !== undefined && lease.heapSeq === node.heapSeq && node.expiresAt > now) {
342	        return true;
343	      }
344	    }
345	    return false;
346	  }
347	
348	  // Remove every node naming `token` from one expiry heap. Used when a
349	  // replay structurally supersedes an expired, unswept lease: the stale
350	  // share never occupied the reconstructed owner table, so its node leaves
351	  // the owner heap without any live-usage movement. Tokens are globally
352	  // unique, so matching the token alone (not the heap sequence) separates a
353	  // superseded lease from a fresh credential that happens to share seq 0.
354	  function removeHeapNodes(heap, token) {
355	    let i = 0;
356	    while (i < heap.nodes.length) {
357	      if (heap.nodes[i].token === token) {
358	        heap.nodes.splice(i, 1);
359	      } else {
360	        i += 1;
361	      }
362	    }
363	    // Restore the heap invariant in linear time after the removals.
364	    const nodes = heap.nodes;
365	    for (let j = (nodes.length >>> 1) - 1; j >= 0; j -= 1) {
366	      let parent = j;
367	      for (;;) {
368	        const left = parent * 2 + 1;
369	        const right = left + 1;
370	        let smallest = parent;
371	        if (left < nodes.length && expiresBefore(nodes[left], nodes[smallest])) {
372	          smallest = left;
373	        }
374	        if (right < nodes.length && expiresBefore(nodes[right], nodes[smallest])) {
375	          smallest = right;
376	        }
377	        if (smallest === parent) {
378	          break;
379	        }
380	        [nodes[parent], nodes[smallest]] = [nodes[smallest], nodes[parent]];
381	        parent = smallest;
382	      }
383	    }
384	  }
385	
386	  function isLive(lease, now) {
387	    return lease !== undefined && lease.expiresAt > now;
388	  }
389	
390	  function resourceStateFor(resource) {
391	    let rs = resourceStates.get(resource);
392	    if (rs === undefined) {
393	      rs = {
394	        capacity: 1,
395	        chain: [],
396	        declared: false,
397	        live: 0,
398	        heap: new ExpiryQueue(),
399	        // Shares observed expired (and so not counted at the current
400	        // reading) but still in the lease table awaiting a sweep. The map is
401	        // reversible: a reading that goes backwards revives entries that are
402	        // live again, exactly as a fresh isLive judgment would.
403	        retired: new Map(),
404	        watermark: -Infinity,
405	        checkedVersion: -1,
406	        // Heap layout version, bumped whenever a node is pushed (a grant or
407	        // a renewal moves a share's expiry): a reconcile at an unchanged
408	        // reading must still run again after a renewal so the new expiry is
409	        // judged at that reading.
410	        version: 0,
411	        // quota -> number of queued positions on this resource under it; the
412	        // set drives quota-indexed wake seeding.
413	        waitRefs: new Map(),
414	      };
415	      resourceStates.set(resource, rs);
416	    }
417	    return rs;
418	  }
419	
420	  function quotaChainFor(leafId) {
421	    const chain = [];
422	    let current = leafId;
423	    while (current !== null && current !== undefined) {
424	      const node = quotas.get(current);
425	      if (node === undefined) {
426	        throw new TypeError(`unknown quota ${String(current)}`);
427	      }
428	      chain.push(node);
429	      current = node.parentId;
430	    }
431	    chain.reverse();
432	    return chain;
433	  }
434	
435	  // Forget a lease from every owner's retired set without touching its
436	  // live usage: the share was already observed expired (a sweep projected
437	  // the retirement before its reclaim event landed).
438	  function purgeRetired(lease) {
439	    const rs = resourceStates.get(lease.resource);
440	    if (rs !== undefined) {
441	      rs.retired.delete(lease.token);
442	    }
443	    for (const quota of lease.chain) {
444	      quota.retired.delete(lease.token);
445	    }
446	  }
447	
448	  // Permanently remove a lease from the table (early release, reclaim, a
449	  // single-occupancy retake, or a replay superseding it). Owners that were
450	  // still counting the share lose it; owners that had already observed it
451	  // expired simply forget its retired entry.
452	  function retirePermanent(lease) {
453	    if (lease === undefined) {
454	      return;
455	    }
456	    const rs = resourceStates.get(lease.resource);
457	    if (rs !== undefined) {
458	      if (!rs.retired.has(lease.token)) {
459	        rs.live -= 1;
460	      }
461	      rs.retired.delete(lease.token);
462	    }
463	    for (const quota of lease.chain) {
464	      if (!quota.retired.has(lease.token)) {
465	        quota.live -= 1;
466	      }
467	      quota.retired.delete(lease.token);
468	    }
469	  }
470	
471	  // Reconcile one occupancy owner (a resource or one quota level) with the
472	  // passed clock reading. Occupancy is judged the way isLive judges it -
473	  // `expiresAt > now` - at every call, so a reading that goes backwards
474	  // revives shares an earlier reading had already retired. The owner's
475	  // watermark makes a monotonic sequence of readings pop lazily in expiry
476	  // order, and a backwards reading walk the retired set back onto the heap.
477	  function reconcile(owner, now) {
478	    const retired = [];
479	    if (now === owner.watermark && owner.version === owner.checkedVersion) {
480	      return retired;
481	    }
482	    if (now > owner.watermark) {
483	      while (owner.heap.size > 0) {
484	        const node = owner.heap.peek();
485	        if (node.expiresAt > now) {
486	          break;
487	        }
488	        owner.heap.pop();
489	        const lease = leases.get(node.token);
490	        if (lease === undefined) {
491	          // Released or reclaimed.
492	          continue;
493	        }
494	        if (lease.heapSeq !== node.heapSeq) {
495	          // Superseded by a renewal: discard the old node without retiring
496	          // anything (its heap entry is stale) and keep scanning.
497	          continue;
498	        }
499	        if (owner.retired.has(node.token)) {
500	          // Either a share that revived after a backwards reading and
501	          // expired again, or a share a replay retake structurally
502	          // superseded: its first retirement already moved this owner's
503	          // usage, so the heap node is simply dropped.
504	          continue;
505	        }
506	        owner.retired.set(node.token, {
507	          heapSeq: node.heapSeq,
508	          expiresAt: node.expiresAt,
509	        });
510	        owner.live -= 1;
511	        retired.push(node);
512	      }
513	    } else {
514	      // The reading moved backwards: every retired share that is live again
515	      // under the earlier reading returns, and its node goes back on the heap
516	      // so a later forward reading retires it in proper expiry order.
517	      for (const [token, record] of owner.retired) {
518	        const lease = leases.get(token);
519	        if (lease === undefined || lease.heapSeq !== record.heapSeq) {
520	          // Released/reclaimed meanwhile, or renewed after a revival: the
521	          // old record describes nothing current.
522	          owner.retired.delete(token);
523	          continue;
524	        }
525	        if (record.expiresAt > now) {
526	          owner.retired.delete(token);
527	          const node = {
528	            token,
529	            expiresAt: record.expiresAt,
530	            heapSeq: record.heapSeq,
531	            order: queueOrder++,
532	          };
533	          owner.heap.push(node);
534	          owner.live += 1;
535	          retired.push({ node, revived: true });
536	        }
537	      }
538	    }
539	    owner.watermark = now;
540	    owner.checkedVersion = owner.version;
541	    return retired;
542	  }
543	
544	  // Project a batch of global reclaim nodes through every owner they
545	  // occupy before wake planning in a sweep. Returns a record able to put
546	  // every owner exactly back if the log write fails.
547	  function projectReclaims(due, now) {
548	    const touched = [];
549	    const seen = new Set();
550	    const touch = (owner) => {
551	      if (owner !== undefined && !seen.has(owner)) {
552	        seen.add(owner);
553	        touched.push({ owner, watermark: owner.watermark, checkedVersion: owner.checkedVersion, retired: [] });
554	      }
555	    };
556	    for (const node of due) {
557	      const lease = leases.get(node.token);
558	      touch(resourceStates.get(lease.resource));
559	      for (const quota of lease.chain) {
560	        touch(quota);
561	      }
562	    }
563	    for (const entry of touched) {
564	      entry.retired = reconcile(entry.owner, now);
565	    }
566	    return touched;
567	  }
568	
569	  function revertProjections(touched) {
570	    for (const entry of touched) {
571	      const { owner } = entry;
572	      for (const item of entry.retired) {
573	        const node = item.node ?? item;
574	        owner.retired.delete(node.token);
575	        if (item.revived) {
576	          owner.live -= 1;
577	        } else {
578	          owner.live += 1;
579	        }
580	        owner.heap.push(node);
581	      }
582	      owner.watermark = entry.watermark;
583	    }
584	  }
585	
586	  function getSlots(resource) {
587	    let set = slots.get(resource);
588	    if (set === undefined) {
589	      set = new Set();
590	      slots.set(resource, set);
591	    }
592	    return set;
593	  }
594	
595	  function addSlot(resource, token) {
596	    getSlots(resource).add(token);
597	  }
598	
599	  function removeSlot(resource, token) {
600	    const set = slots.get(resource);
601	    if (set === undefined) {
602	      return false;
603	    }
604	    const removed = set.delete(token);
605	    if (removed && set.size === 0) {
606	      slots.delete(resource);
607	    }
608	    return removed;
609	  }
610	
611	  // Drop expired-but-unswept credentials from a single-occupancy resource
612	  // that is about to be granted: the resource is free, and a retaken lease
613	  // must never be reported as reclaimed later. Mirrors the retake rule. Share
614	  // resources never displace anyone, so they never call this.
615	  function dropStaleSlots(resource, now) {
616	    const rs = resourceStates.get(resource);
617	    if (rs === undefined) {
618	      return;
619	    }
620	    // Permanent removal consults each owner's retired set itself and
621	    // only decrements owners that were still counting the share, so no
622	    // prior reconcile is needed here.
623	    const set = slots.get(resource);
624	    if (set === undefined) {
625	      return;
626	    }
627	    for (const token of [...set]) {
628	      const lease = leases.get(token);
629	      if (!isLive(lease, now)) {
630	        retirePermanent(lease);
631	        leases.delete(token);
632	        set.delete(token);
633	      }
