2296	    // against the resource epoch it was supposed to carry. Recovery never
2297	    // advances an epoch: the map comes back exactly as it was folded, and
2298	    // only tail acquire events replayed afterwards move it on.
2299	    const hasEpochSection = Array.isArray(snapshot.epochs);
2300	    if (hasEpochSection) {
