test('transfer throws TypeError on bad token, holder or ttl arguments', () => {
  const registry = createRegistry({ ttlMs: 100, clock: fakeClock(0) });
  const lease = registry.acquire('r', 'alice');
  for (const [token, holder] of [
    [undefined, 'bob'],
    [null, 'bob'],
